window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[317]={"id":"317","numero":317,"titre":"Syndromes myéloprolifératifs — LMC, Vaquez, TE","objectifs":[{"id":"317-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition des syndromes myéloprolifératifs et leur classification","contenu":"<p>Les <span class=\"kw-def\">syndromes myéloprolifératifs</span> (SMP), ou <span class=\"kw-def\">néoplasies myéloprolifératives</span>, sont des <strong><span class=\"kw-def\">hémopathies myéloïdes clonales</span></strong> touchant une <strong>cellule souche hématopoïétique (CSH)</strong>. Ils aboutissent à une <strong>hyperplasie médullaire globale</strong> et à une augmentation de production des éléments figurés du sang.</p>\n      <p>Notion-clé : la moelle fabrique <strong>trop de cellules</strong>, mais ce sont des <strong>cellules matures de bonne qualité</strong> — les symptômes découlent de l'<strong>excès</strong> de ces cellules, pas d'un défaut de qualité.</p>\n      <p>Quatre entités composent les SMP, classées selon la <strong>lignée myéloïde prédominante</strong> :</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Lignée touchée</th><th>Anomalie génétique</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">LMC</span></strong> — leucémie myéloïde chronique</td><td><strong>Granulocytaire</strong> (polynucléaires)</td><td><span class=\"kw-bio\">t(9;22)</span> → BCR-ABL — <span class=\"kw-chiffre\">100 %</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Polyglobulie primitive</span></strong> (maladie de Vaquez)</td><td><strong>Érythroblastique</strong> (globules rouges)</td><td><span class=\"kw-bio\">JAK2</span> — <span class=\"kw-chiffre\">95 %</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Thrombocytémie essentielle</span></strong></td><td><strong>Mégacaryocytaire</strong> (<span class=\"kw-bio\">plaquettes</span>)</td><td><span class=\"kw-bio\">JAK2</span> <span class=\"kw-chiffre\">50 %</span> ; <span class=\"kw-bio\">CALR</span> <span class=\"kw-chiffre\">25 %</span> ; <span class=\"kw-bio\">MPL</span> <span class=\"kw-chiffre\">5 %</span></td></tr>\n          <tr><td><span class=\"kw-def\">Myélofibrose primitive</span> <em>(rang C)</em></td><td>Mégacaryocytaire ; fibrose médullaire</td><td><span class=\"kw-bio\">JAK2</span> <span class=\"kw-chiffre\">50 %</span> ; <span class=\"kw-bio\">CALR</span> <span class=\"kw-chiffre\">35 %</span> ; <span class=\"kw-bio\">MPL</span> <span class=\"kw-chiffre\">10 %</span></td></tr>\n        </tbody>\n      </table>\n      <p>La <strong>classification</strong> repose sur la présence du <strong>chromosome de Philadelphie (Ph)</strong> :</p>\n      <ul>\n        <li><strong>SMP Ph+</strong> : la <span class=\"kw-def\">LMC</span> seule — <span class=\"kw-chiffre\">100 %</span> des cas portent la translocation <span class=\"kw-bio\">BCR-ABL</span>.</li>\n        <li><strong>SMP Ph−</strong> : Vaquez, TE et myélofibrose primitive — principalement <span class=\"kw-bio\">JAK2</span>+, parfois <span class=\"kw-bio\">CALR</span>+ ou <span class=\"kw-bio\">MPL</span>+. Ces mutations sont considérées comme <strong>exclusives</strong> (non associées entre elles).</li>\n      </ul>\n      <p><strong>Épidémiologie</strong> : incidence de <span class=\"kw-chiffre\">1 à 2 cas / 100 000 habitants / an</span> par type (la myélofibrose primitive est plus rare) ; adulte de la seconde moitié de la vie (<span class=\"kw-chiffre\">&gt; 50 ans</span>) ; <strong>prédominance masculine</strong>, sauf la TE (prédominance féminine).</p>\n      <p><strong>Présentation commune</strong> : <span class=\"kw-clinique\">splénomégalie</span> (mais <strong>absence d'<span class=\"kw-clinique\">adénopathie</span></strong> en général), risque accru de <span class=\"kw-alerte\">thromboses veineuses et artérielles</span>, augmentation des cellules circulantes à la <span class=\"kw-bio\">NFS</span>. Ce sont des maladies d'évolution lente, compatibles avec une survie prolongée.</p>\n      <p><strong>Risques communs</strong> aux SMP :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Thromboses</span> veineuses et artérielles — risque initial, favorisé par l'augmentation de la <strong>viscosité sanguine</strong>.</li>\n        <li><span class=\"kw-alerte\">Acutisation en leucémie aiguë myéloïde</span> — risque à moyen/long terme, de pronostic très sombre, parfois précédée d'une phase de myélodysplasie.</li>\n        <li>Crises de <span class=\"kw-clinique\">goutte</span>, lithiases urinaires, <span class=\"kw-clinique\">priapisme</span> — liés au renouvellement cellulaire et à l'hyperuricémie.</li>\n      </ul>\n      <p><strong>Risque spécifique</strong> : la maladie de Vaquez et la TE peuvent évoluer vers une <span class=\"kw-alerte\">myélofibrose secondaire</span> ; la myélofibrose primitive est la forme la plus <strong>grave</strong> et la plus <strong>rare</strong>.</p>\n      <div class=\"callout callout-warn\"><strong>À distinguer.</strong> SMP = cellules matures <strong>normales</strong> en excès. À ne pas confondre avec la <span class=\"kw-def\">leucémie aiguë</span> (blastes immatures, blocage de maturation) ni le <span class=\"kw-def\">syndrome myélodysplasique</span> (cellules dysplasiques de mauvaise qualité + blastes) — piège classique en annale.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 315 — Leucémie aiguë · 316 — Syndrome myélodysplasique</em></p>","frequence":1},{"id":"317-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les bases physiopathologiques de la leucémie myéloïde chronique (LMC), de la polyglobulie primitive (PV) et de la thrombocytémie essentielle (TE)","contenu":"<p>Les SMP partagent un <strong>tronc physiopathologique commun</strong>. Ce sont des <span class=\"kw-def\">hémopathies malignes chroniques</span>, <strong>acquises et clonales</strong>, qui touchent la <strong>cellule souche hématopoïétique (CSH)</strong>.</p>\n      <p>L'anomalie oncogénique correspond le plus souvent à la <strong>dérégulation d'une protéine à activité tyrosine kinase</strong> : <span class=\"kw-bio\">BCR-ABL</span> dans la LMC, <span class=\"kw-bio\">JAK2</span> (mutation V617F) dans les SMP non-LMC. Il en résulte une <strong>activation anormale et permanente de la signalisation intracellulaire</strong>, responsable de :</p>\n      <ul>\n        <li>une <strong>hyperproduction de cellules myéloïdes matures</strong> par la moelle ;</li>\n        <li>des cellules <strong>morphologiquement normales</strong>, car il n'y a <span class=\"kw-alerte\">pas de blocage de la maturation</span> (à la différence des leucémies aiguës) ;</li>\n        <li>une prolifération devenue <strong>indépendante des facteurs de croissance hématopoïétiques</strong>.</li>\n      </ul>\n      <table >\n        <thead><tr><th>Entité</th><th>Anomalie génétique</th><th>Mécanisme moléculaire</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">LMC</span></strong></td><td>Translocation <span class=\"kw-bio\">t(9;22)</span> acquise sur la CSH</td><td>Recombinaison entre le bras long du chromosome 9 (oncogène <span class=\"kw-bio\">ABL</span>, <em>Abelson</em>) et celui du chromosome 22 (gène <span class=\"kw-bio\">BCR</span>, <em>Break Cluster Region</em>). Le chromosome 22 raccourci = <strong>chromosome de Philadelphie (Ph1)</strong>. L'ARNm de fusion code une <strong>protéine BCR-ABL</strong> à <strong>activité tyrosine kinase constitutive</strong> → <span class=\"kw-bio\">hyperleucocytose</span> (prolifération granuleuse + baisse de l'apoptose) et <span class=\"kw-bio\">myélémie</span> (perte de l'adhérence au stroma médullaire).</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Polyglobulie de Vaquez</span></strong></td><td>Mutation <span class=\"kw-bio\">JAK2 V617F</span> — <span class=\"kw-chiffre\">95 %</span></td><td>Pas d'anomalie cytogénétique spécifique, <strong>caryotype souvent normal</strong>. Production augmentée de globules rouges <strong>sans stimulation extérieure</strong>, avec <strong>autonomie de croissance vis-à-vis de l'EPO</strong> : pousse de colonies érythroblastiques endogènes in vitro, même en l'absence d'EPO. Rares mutations de l'exon 12 de JAK2.</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Thrombocytémie essentielle</span></strong></td><td><span class=\"kw-bio\">JAK2</span> <span class=\"kw-chiffre\">50 %</span> ; <span class=\"kw-bio\">CALR</span> <span class=\"kw-chiffre\">25 %</span> ; <span class=\"kw-bio\">MPL</span> <span class=\"kw-chiffre\">5 %</span></td><td><strong>JAK2 :</strong> signalisation du récepteur de la thrombopoïétine<br><strong>CALR :</strong> la calréticuline mutée renforce sa liaison au récepteur de la thrombopoïétine<br><strong>MPL :</strong> récepteur de la thrombopoïétine activé de façon constitutive<br>Toutes ces mutations convergent vers l'<strong>activation de la voie JAK-STAT</strong>, à l'origine de la prolifération cellulaire.</td></tr>\n        </tbody>\n      </table>\n      <p>La <span class=\"kw-bio\">myélémie</span> désigne la présence, dans le sang périphérique, de cellules immatures de la lignée <strong>granulocytaire</strong> (<span class=\"kw-bio\">myélocytes</span>, <span class=\"kw-bio\">métamyélocytes</span>) — en plus des <span class=\"kw-bio\">polynucléaires neutrophiles</span> en excès.</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> L'anomalie oncogénique d'un SMP touche la <strong>CSH</strong>, et non les cellules matures — c'est un piège récurrent en annale. Elle est ensuite retrouvée dans <strong>toutes les cellules matures myéloïdes</strong> issues du clone.</div>","frequence":5},{"id":"317-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principales circonstances diagnostiques et les signes cliniques de la LMC, de la PV et de la TE","contenu":"<p>Le SMP est <strong>fréquemment découvert de façon fortuite</strong>, sur un <span class=\"kw-bio\">hémogramme</span> systématique (≈ <span class=\"kw-chiffre\">40 %</span> des LMC concernent un patient asymptomatique). Les signes cliniques d'appel diffèrent ensuite selon l'entité.</p>\n      <table >\n        <thead><tr><th></th><th>LMC</th><th>Maladie de Vaquez</th><th>Thrombocytémie essentielle</th></tr></thead>\n        <tbody>\n          <tr><td>Âge médian</td><td><span class=\"kw-chiffre\">67 ans</span></td><td><span class=\"kw-chiffre\">&gt; 50 ans</span></td><td><span class=\"kw-chiffre\">70 ans</span></td></tr>\n          <tr><td>Sex-ratio</td><td>Prédominance masculine (<span class=\"kw-chiffre\">1,3 H / 1 F</span>)</td><td>Légère prédominance masculine</td><td>Légère prédominance <strong>féminine</strong></td></tr>\n          <tr><td>Signe(s) d'appel évocateur(s)</td><td><span class=\"kw-clinique\">Altération de l'état général</span> ; <span class=\"kw-clinique\">splénomégalie</span> ; bilan d'une <span class=\"kw-clinique\">goutte</span></td><td><span class=\"kw-clinique\">Prurit aquagénique</span> (très évocateur) ; <span class=\"kw-clinique\">érythrose cutanéo-muqueuse</span> du visage et des mains ; <span class=\"kw-clinique\">érythromélalgie</span></td><td>Le plus souvent <strong>asymptomatique</strong> ; <span class=\"kw-clinique\">érythromélalgie</span></td></tr>\n          <tr><td>Splénomégalie</td><td><strong>Fréquente</strong>, modérée à volumineuse, isolée ; débord à <strong>mesurer</strong> (scores Sokal et ELTS)</td><td>Présente (≈ <span class=\"kw-chiffre\">50 %</span>)</td><td>Habituellement <strong>absente</strong> (mais possible)</td></tr>\n          <tr><td>Complications révélatrices</td><td>Manifestations <span class=\"kw-alerte\">thrombotiques</span> (moins fréquentes que dans les autres SMP) : <span class=\"kw-clinique\">priapisme</span>, occlusion rétinienne, <span class=\"kw-def\">AVC</span>, <span class=\"kw-def\">AIT</span> ; syndrome anémique possible</td><td>Signes d'<span class=\"kw-alerte\">hyperviscosité</span> : thromboses, <span class=\"kw-clinique\">HTA</span>, signes neurosensoriels (<span class=\"kw-clinique\">céphalées</span>, <span class=\"kw-clinique\">vertiges</span>, troubles visuels, <span class=\"kw-clinique\">paresthésies</span>, acouphènes)</td><td><span class=\"kw-alerte\">Thromboses</span> artérielles (cérébrales, coronaires, membres) et veineuses ; syndrome <span class=\"kw-etio\">hémorragique</span> rare</td></tr>\n        </tbody>\n      </table>\n      <p>L'<span class=\"kw-clinique\">érythromélalgie</span> (douleurs paroxystiques des extrémités, à type de brûlure, avec rougeur et chaleur) est commune à la maladie de Vaquez et à la TE ; elle <strong>cède immédiatement à la prise d'<span class=\"kw-ttt\">aspirine</span></strong>.</p>\n      <div class=\"callout callout-danger\"><strong>Urgence.</strong> Dans la maladie de Vaquez, des signes cliniques d'<span class=\"kw-alerte\">hyperviscosité</span> ou un <span class=\"kw-alerte\">hématocrite &gt; 60 %</span> constituent une <strong>urgence médicale</strong>.</div>\n      <div class=\"callout callout-warn\"><strong>Pièges classiques.</strong> Les SMP ne donnent <strong>jamais d'<span class=\"kw-clinique\">adénopathie</span></strong>. La LMC ne donne <span class=\"kw-alerte\">jamais de polyglobulie</span> — à la différence de la maladie de Vaquez, qui en est précisément définie.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP</em></p>","frequence":10},{"id":"317-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les anomalies biologiques observées au moment du diagnostic de LMC, de PV et TE","contenu":"<p>Les anomalies de l'<span class=\"kw-bio\">hémogramme</span> orientent vers le SMP ; leur confirmation repose ensuite sur des examens génétiques et médullaires <strong>propres à chaque entité</strong>.</p>\n      <table >\n        <thead><tr><th></th><th>LMC</th><th>Maladie de Vaquez</th><th>Thrombocytémie essentielle</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">NFS</span> caractéristique</td><td><span class=\"kw-bio\">Hyperleucocytose</span> considérable <span class=\"kw-chiffre\">&gt; 50-100 G/L</span> (PNN, PNB, PNE de morphologie normale) ; <span class=\"kw-bio\">basophilie</span> ; <span class=\"kw-bio\">myélémie</span> équilibrée (métamyélocytes &gt; myélocytes &gt; promyélocytes) ; <strong>pas de hiatus leucémique</strong> ; hyperplaquettose fréquente</td><td><span class=\"kw-bio\">Polyglobulie</span> : <span class=\"kw-chiffre\">Hb &gt; 16,5 g/dL</span> (H) ou <span class=\"kw-chiffre\">&gt; 16 g/dL</span> (F), <span class=\"kw-chiffre\">Ht &gt; 49 %</span> (H) ou <span class=\"kw-chiffre\">&gt; 48 %</span> (F) ; hyperleucocytose modérée sans myélémie ; hyperplaquettose ; <span class=\"kw-bio\">VS</span> très basse</td><td><span class=\"kw-bio\">Thrombocytose</span> <span class=\"kw-chiffre\">&gt; 450 G/L</span>, le plus souvent isolée (parfois <span class=\"kw-chiffre\">2000-3000 G/L</span>) ; discrète hyper-PNN sans myélémie possible ; lignée rouge normale</td></tr>\n          <tr><td>Examen confirmant le diagnostic</td><td><strong><span class=\"kw-bio\">PCR</span> <span class=\"kw-bio\">BCR-ABL</span></strong> dans le sang — <span class=\"kw-bio\">hémogramme</span> évocateur + détection de BCR-ABL = diagnostic affirmé</td><td>Mutation <span class=\"kw-bio\">JAK2 V617F</span> ; <span class=\"kw-bio\">EPO sérique</span> basse ; critères diagnostiques (3 majeurs, ou les 2 premiers majeurs + 1 mineur)</td><td>Mutation <span class=\"kw-bio\">JAK2</span> (1ᵉʳ temps), puis <span class=\"kw-bio\">CALR</span> et <span class=\"kw-bio\">MPL</span> (2ᵉ temps), puis <span class=\"kw-bio\">BCR-ABL</span> (3ᵉ temps, pour éliminer une LMC)</td></tr>\n          <tr><td>Myélogramme</td><td><strong>Obligatoire</strong>, avec <span class=\"kw-bio\">caryotype médullaire</span> (recherche du chromosome de Philadelphie, exclusion d'un excès de blastes)</td><td><span class=\"kw-alerte\">Non</span> — pas de myélogramme</td><td><span class=\"kw-alerte\">Non</span> — pas de myélogramme</td></tr>\n          <tr><td><span class=\"kw-bio\">Biopsie</span> ostéo-médullaire (BOM)</td><td>Non nécessaire</td><td><strong>Oui</strong> : panmyélose (hypercellularité des 3 lignées) + prolifération mégacaryocytaire pléomorphe</td><td><strong>Oui</strong> : prolifération mégacaryocytaire, mégacaryocytes matures</td></tr>\n          <tr><td>Autres examens</td><td>Bilan métabolique : <span class=\"kw-bio\">uricémie</span>, <span class=\"kw-bio\">LDH</span>, fonction hépatique, fonction rénale</td><td><span class=\"kw-bio\">Gaz du sang</span> ou <span class=\"kw-bio\">SaO2</span> ; <span class=\"kw-imagerie\">échographie</span> abdomino-pelvienne</td><td>—</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège majeur.</strong> Dans la maladie de Vaquez et la TE, on réalise une <strong>BOM</strong>, <span class=\"kw-alerte\">jamais de myélogramme</span>. À l'inverse, la LMC impose un <strong>myélogramme avec caryotype</strong>, la BOM y étant inutile.</div>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Devant l'association <span class=\"kw-bio\">polyglobulie</span> + <span class=\"kw-bio\">hyperleucocytose</span> + <span class=\"kw-bio\">hyperplaquettose</span>, évoquer systématiquement une <span class=\"kw-def\">maladie de Vaquez</span>. Pour interpréter une polyglobulie, se fonder sur l'<span class=\"kw-bio\">hémoglobine</span> et l'<span class=\"kw-bio\">hématocrite</span>, <strong>jamais sur le chiffre de globules rouges</strong>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 212 — <span class=\"kw-bio\">Hémogramme</span> · 275 — Splénomégalie</em></p>","frequence":6},{"id":"317-5","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Savoir que le pronostic des syndromes myéloprolifératifs a été spectaculairement amélioré par l'arrivée des inhibiteurs de tyrosine kinase","contenu":"<p>L'arrivée des <strong><span class=\"kw-ttt\">inhibiteurs de tyrosine kinase (ITK)</span></strong> a <strong>spectaculairement transformé</strong> le pronostic de la LMC : grâce à eux, la <strong>survie des patients atteints de LMC rejoint celle de la population générale</strong>.</p>\n      <p><strong>Mécanisme et modalités des ITK</strong> :</p>\n      <ul>\n        <li>Ils <strong>bloquent l'activité tyrosine kinase</strong> de la protéine <span class=\"kw-bio\">BCR-ABL</span> en empêchant l'ATP de s'y fixer.</li>\n        <li>Administration <strong>per os</strong>.</li>\n        <li>Chef de file en 1ʳᵉ ligne : l'<span class=\"kw-ttt\">imatinib</span> (<span class=\"kw-chiffre\">400 mg/j</span>) ; effets indésirables chroniques — <span class=\"kw-clinique\">diarrhées</span>, douleurs et crampes musculaires.</li>\n        <li>En cas d'échec ou d'intolérance : ITK de 2ᵉ génération (<span class=\"kw-ttt\">dasatinib</span>, <span class=\"kw-ttt\">nilotinib</span>, <span class=\"kw-ttt\">bosutinib</span>). En cas de résistance : ITK de 3ᵉ génération (<span class=\"kw-ttt\">ponatinib</span>).</li>\n      </ul>\n      <p>Évolution naturelle de la LMC <strong>non traitée</strong>, stéréotypée en <strong>3 phases</strong> :</p>\n      <table >\n        <thead><tr><th>Phase</th><th>Durée</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Chronique</strong></td><td><span class=\"kw-chiffre\">5 ans</span> en moyenne</td><td>Majorité des patients ; progression vers les phases suivantes devenue <strong>exceptionnelle depuis les ITK</strong></td></tr>\n          <tr><td><strong>Accélération</strong></td><td><span class=\"kw-chiffre\">12-18 mois</span></td><td><span class=\"kw-clinique\">Amaigrissement</span>, <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">sueurs nocturnes</span>, douleurs osseuses ; apparition d'un <span class=\"kw-alerte\">excès de blastes</span> sanguins</td></tr>\n          <tr><td><strong>Blastique</strong></td><td>Terminale</td><td>Transformation en <span class=\"kw-alerte\">leucémie aiguë</span> (myéloïde 2/3, lymphoblastique B 1/3) — pronostic <strong>très défavorable</strong></td></tr>\n        </tbody>\n      </table>\n      <p>La LMC est un <strong>modèle de suivi hématologique</strong> : l'observance doit être parfaite, et la surveillance régulière associe l'examen <strong>clinique</strong> (palpation splénique), l'<span class=\"kw-bio\">hémogramme</span>, la <span class=\"kw-bio\">cytogénétique</span> (caryotype tous les <span class=\"kw-chiffre\">6 mois</span>) et la <span class=\"kw-bio\">biologie moléculaire</span> (transcrit BCR-ABL dans le sang, trimestriel puis semestriel, <strong>à vie</strong>).</p>\n      <p>Pronostic des SMP Ph− :</p>\n      <ul>\n        <li><strong>Maladie de Vaquez</strong> : survie <strong>diminuée</strong> par rapport à la population générale (survie médiane de l'ordre de <span class=\"kw-chiffre\">75 % à 15 ans</span>).</li>\n        <li><strong>Thrombocytémie essentielle</strong> : espérance de vie <strong>voisine de celle de la population générale</strong> si la maladie est correctement prise en charge — c'est le <strong>SMP le moins grave</strong>.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Avant les ITK, la LMC évoluait inéluctablement vers l'<span class=\"kw-alerte\">acutisation</span>. Depuis, la phase chronique se prolonge chez la majorité des patients et la transformation aiguë est devenue exceptionnelle — c'est l'amélioration « spectaculaire » que vise l'intitulé de cet objectif.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 315 — Leucémie aiguë</em></p>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p><strong>Maladie de Vaquez <span class=\"q\">— hyperviscosité</span></strong></p><p>prudence chez le <span class=\"kw-clinique\">sujet âgé</span> ; lutte contre les <span class=\"kw-etio\">facteurs de risque cardiovasculaire</span></p><ul><li><span class=\"kw-alerte\">Urgence médicale</span> si <span class=\"kw-clinique\">signes d'hyperviscosité</span> ou <span class=\"kw-chiffre\">Ht &gt; 60 %</span></li><li><span class=\"kw-ttt\">Saignée</span> en urgence (ponction de <span class=\"kw-chiffre\">300-400 mL</span>) : <span class=\"kw-ttt\">aucune contre-indication</span>, réalisable dans n'importe quelle structure de soins</li><li><span class=\"kw-ttt\">Aspirine</span> <span class=\"kw-chiffre\">100 mg/j</span> à dose antiagrégante, systématique</li></ul><p><strong>Thrombose splanchnique <span class=\"q\">— Budd-Chiari, thrombose porte</span></strong></p><p>la <span class=\"kw-def\">polyglobulie</span> peut être masquée par un <span class=\"kw-clinique\">hypersplénisme</span> / hémodilution</p><ul><li><span class=\"kw-alerte\">Thrombose veineuse splanchnique</span> (<span class=\"kw-def\">syndrome de Budd-Chiari</span>, <span class=\"kw-def\">thrombose porte</span>) parfois révélatrice</li><li>Rechercher <span class=\"kw-bio\">systématiquement la mutation JAK2 V617F</span> même si l'<span class=\"kw-bio\">hémogramme</span> est normal</li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Signes d'hyperviscosité</span> : <span class=\"kw-alerte\">thromboses</span> veineuses/artérielles, <span class=\"kw-clinique\">HTA</span>, signes neurosensoriels (<span class=\"kw-clinique\">céphalées</span>, <span class=\"kw-clinique\">vertiges</span>, <span class=\"kw-clinique\">troubles visuels</span>, <span class=\"kw-clinique\">paresthésies</span>, <span class=\"kw-clinique\">acouphènes</span>)</li><li><span class=\"kw-alerte\">Hématocrite</span> <span class=\"kw-chiffre\">&gt; 60 %</span> → urgence médicale (Vaquez)</li><li><span class=\"kw-alerte\">Thrombose</span> artérielle (<span class=\"kw-etio\">AVC</span>) ou veineuse, parfois de territoire inhabituel (<span class=\"kw-def\">Budd-Chiari</span>, <span class=\"kw-def\">thrombose porte</span>) — 1ʳᵉ cause de mortalité de la Vaquez</li><li><span class=\"kw-alerte\">Thrombocytose extrême</span> <span class=\"kw-chiffre\">&gt; 1500 G/L</span> (TE) → risque <span class=\"kw-alerte\">hémorragique</span> par <span class=\"kw-def\">maladie de Willebrand acquise</span></li><li><span class=\"kw-alerte\">Phase d'accélération</span> de la LMC : <span class=\"kw-clinique\">amaigrissement</span>, <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">sueurs nocturnes</span>, douleurs osseuses + <span class=\"kw-alerte\">excès de blastes</span> sanguins</li><li><span class=\"kw-alerte\">Acutisation</span> en <span class=\"kw-etio\">leucémie aiguë myéloïde</span> : risque commun à moyen/long terme de tous les SMP, pronostic très sombre</li></ul>","principes":"<p>Deux logiques : la <span class=\"kw-def\">LMC (Ph+)</span> relève d'une <span class=\"kw-ttt\">thérapie ciblée par ITK</span> ; les <span class=\"kw-def\">SMP Ph−</span> (Vaquez, TE) visent avant tout la <span class=\"kw-def\">prévention des thromboses</span>.</p><p><strong>LMC <span class=\"q\">— Ph+ / BCR-ABL</span></strong></p><p>grâce aux ITK la <span class=\"kw-def\">survie rejoint celle de la population générale</span> — <span class=\"kw-ttt\">observance parfaite</span> indispensable</p><ul><li><span class=\"kw-ttt\">Inhibiteur de tyrosine kinase (ITK)</span> per os, 1ʳᵉ ligne : <span class=\"kw-ttt\">imatinib</span> <span class=\"kw-chiffre\">400 mg/j</span> (bloque l'activité tyrosine kinase de BCR-ABL)</li><li>EI chroniques de l'imatinib : <span class=\"kw-clinique\">diarrhées</span>, <span class=\"kw-clinique\">crampes / douleurs musculaires</span></li><li>Échec/intolérance : <span class=\"kw-ttt\">ITK de 2ᵉ génération</span> (dasatinib, nilotinib, bosutinib) ; résistance : <span class=\"kw-ttt\">ponatinib</span> (3ᵉ génération)</li></ul><p><strong>Maladie de Vaquez</strong></p><p>certains myélofreinateurs ont un <span class=\"kw-ci\">potentiel leucémogène à long terme</span></p><ul><li>Objectif : <span class=\"kw-def\">prévention des accidents thromboemboliques</span></li><li><span class=\"kw-ttt\">Saignées</span> = 1er traitement de tous les patients, jusqu'à <span class=\"kw-chiffre\">Ht &lt; 45 %</span></li><li><span class=\"kw-ttt\">Aspirine</span> <span class=\"kw-chiffre\">100 mg/j</span> systématique</li><li><span class=\"kw-ttt\">Myélofreinateur</span> (<span class=\"kw-ttt\">hydroxyurée</span>) si <span class=\"kw-chiffre\">âge &gt; 60 ans</span>, ATCD de thrombose ou saignées mal tolérées</li></ul><p><strong>Thrombocytémie essentielle</strong></p><p>TE = <span class=\"kw-def\">SMP le moins grave</span>, espérance de vie voisine de la population générale</p><ul><li>Objectif : <span class=\"kw-def\">prévention des thromboses</span> (comme la Vaquez)</li><li><span class=\"kw-ttt\">Aspirine</span> antiagrégante ; <span class=\"kw-ttt\">anticoagulant</span> si ATCD thrombotique</li><li><span class=\"kw-ttt\">Myélofreinateur</span> (<span class=\"kw-ttt\">hydroxyurée</span>, <span class=\"kw-ttt\">anagrélide</span>) si <span class=\"kw-chiffre\">âge &gt; 60 ans</span>, <span class=\"kw-chiffre\">plaquettes &gt; 1500 G/L</span> ou ATCD de thrombose / hémorragie</li></ul>","suivi":"<p>La <span class=\"kw-def\">LMC</span> est le <span class=\"kw-def\">modèle de suivi hématologique</span> : surveillance régulière et <span class=\"kw-ttt\">observance parfaite</span>.</p><p><strong>LMC <span class=\"q\">— surveillance à vie</span></strong></p><ul><li>Clinique : <span class=\"kw-clinique\">palpation splénique</span> (la splénomégalie doit disparaître sous traitement)</li><li><span class=\"kw-bio\">Hémogramme</span> ; <span class=\"kw-bio\">cytogénétique</span> : caryotype tous les <span class=\"kw-chiffre\">6 mois</span> jusqu'à t(9;22) indétectable</li><li><span class=\"kw-bio\">Biologie moléculaire</span> : transcrit <span class=\"kw-bio\">BCR-ABL</span> dans le sang, trimestriel puis semestriel, <span class=\"kw-chiffre\">à vie</span></li></ul><p><strong>Maladie de Vaquez</strong></p><ul><li>Sous <span class=\"kw-ttt\">hydroxyurée</span> : <span class=\"kw-bio\">NFS</span> mensuelle ; maintenir <span class=\"kw-chiffre\">Ht &lt; 45 %</span></li><li>Pronostic : <span class=\"kw-def\">survie diminuée</span> vs population générale (médiane ~<span class=\"kw-chiffre\">75 % à 15 ans</span>)</li><li>Transformations après <span class=\"kw-chiffre\">10-20 ans</span> : <span class=\"kw-etio\">myélofibrose secondaire</span>, <span class=\"kw-etio\">SMD</span>, <span class=\"kw-etio\">LAM</span></li></ul><p><strong>Thrombocytémie essentielle</strong></p><ul><li>Sous <span class=\"kw-ttt\">hydroxyurée</span> : <span class=\"kw-bio\">NFS</span> mensuelle ; sous <span class=\"kw-ttt\">anagrélide</span> : surveillance <span class=\"kw-clinique\">cardiologique</span> (effet inotrope positif)</li><li>Pronostic : espérance de vie ≈ population générale ; transformation rare après <span class=\"kw-chiffre\">&gt; 20 ans</span></li></ul>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/chronic-myeloid-leukaemia","label":"Radiopaedia : Chronic myeloid leukaemia"},{"href":"https://radiopaedia.org/articles/polycythaemia-vera","label":"Radiopaedia : Polycythaemia vera"},{"href":"https://radiopaedia.org/articles/myeloproliferative-neoplasm-1","label":"Radiopaedia : Myeloproliferative neoplasm 1"},{"href":"https://radiopaedia.org/articles/essential-thrombocythaemia","label":"Radiopaedia : Essential thrombocythaemia"}],"cards":[{"i":"20e4419040be","n":317,"o":"317-1","u":"Définition","t":"Connaître la définition des syndromes myéloprolifératifs et leur classification","q":"Précisez la classification des syndromes myéloprolifératifs (SMP) en fonction de la mutation génétique et de la lignée cellulaire prédominante.","a":"<p>La classification des SMP repose principalement sur la présence du <strong>chromosome de Philadelphie (Ph)</strong> ou de certaines mutations génétiques :</p><ul><li><strong>SMP Ph+</strong> : Il s'agit uniquement de la <strong>leucémie myéloïde chronique (LMC)</strong>, caractérisée par une prolifération granulocytaire et la présence systématique de la translocation <strong>t(9;22)</strong> formant le gène <strong>BCR-ABL</strong>.</li><li><strong>SMP Ph-</strong> : Ce groupe inclut la <strong>polyglobulie primitive (maladie de Vaquez)</strong> avec prolifération érythroblastique (mutation <strong>JAK2</strong> dans 95% des cas), la <strong>thrombocytémie essentielle (TE)</strong> avec prolifération mégacaryocytaire (mutations <strong>JAK2, CALR ou MPL</strong>), et la <strong>myélofibrose primitive</strong> avec prolifération mégacaryocytaire et fibrose médullaire (mutations <strong>JAK2, CALR ou MPL</strong>). Ces mutations sont considérées comme exclusives.</li></ul>"},{"i":"4fd5562d94b0","n":317,"o":"317-1","u":"Définition","t":"Connaître la définition des syndromes myéloprolifératifs et leur classification","q":"Quels sont les pièges diagnostiques à éviter concernant la définition des syndromes myéloprolifératifs ?","a":"<p>Il ne faut pas confondre les syndromes myéloprolifératifs (SMP) avec :</p><ul><li>Les <strong>leucémies aiguës</strong>, qui se caractérisent par la prolifération de blastes immatures et un blocage de maturation.</li><li>Les <strong>syndromes myélodysplasiques</strong>, où l'on observe la présence de cellules dysplasiques de mauvaise qualité et des anomalies de maturation.</li></ul><p>Dans les SMP, l'excès concerne des <strong>cellules matures de qualité normale</strong>.</p>"},{"i":"d5c2b2cfffcb","n":317,"o":"317-1","u":"Définition","t":"Connaître la définition des syndromes myéloprolifératifs et leur classification","q":"Quelle est la définition générale des syndromes myéloprolifératifs (SMP) ?","a":"<p>Les syndromes myéloprolifératifs sont des <strong>hémopathies myéloïdes clonales</strong>, c'est-à-dire des affections de la moelle osseuse touchant une <strong>cellule souche hématopoïétique (CSH)</strong>.</p><p>Ils se caractérisent par une <strong>hyperplasie médullaire globale</strong> entraînant une <strong>augmentation de la production de cellules matures de bonne qualité</strong> dans le sang.</p>"},{"i":"10e81d331115","n":317,"o":"317-3","u":"Diagnostic positif","t":"Connaître les principales circonstances diagnostiques et les signes cliniques de la LMC, de la PV et de la TE","q":"Quel piège diagnostique concernant les adénopathies doit-on connaître pour les syndromes myéloprolifératifs (SMP) ?","a":"<p>Les syndromes myéloprolifératifs ne donnent <strong>jamais d'adénopathie</strong>.</p>"},{"i":"542831d0c02e","n":317,"o":"317-3","u":"Diagnostic positif","t":"Connaître les principales circonstances diagnostiques et les signes cliniques de la LMC, de la PV et de la TE","q":"Quel piège diagnostique concernant la polyglobulie doit-on connaître pour la LMC ?","a":"<p>La Leucémie Myéloïde Chronique (LMC) ne donne <strong>jamais de polyglobulie</strong>, à la différence de la maladie de Vaquez qui en est précisément définie.</p>"},{"i":"6149b8be08ad","n":317,"o":"317-3","u":"Diagnostic positif","t":"Connaître les principales circonstances diagnostiques et les signes cliniques de la LMC, de la PV et de la TE","q":"Quelle est la particularité clinique de l'érythromélalgie dans les syndromes myéloprolifératifs ?","a":"<p>L'érythromélalgie (douleurs paroxystiques des extrémités, à type de brûlure, avec rougeur et chaleur) est commune à la <strong>maladie de Vaquez</strong> et à la <strong>thrombocytémie essentielle (TE)</strong>. Elle cède immédiatement à la prise d'<strong>aspirine</strong>.</p>"},{"i":"8a6b1c8ddf96","n":317,"o":"317-3","u":"Diagnostic positif","t":"Connaître les principales circonstances diagnostiques et les signes cliniques de la LMC, de la PV et de la TE","q":"Quelle est la principale circonstance de découverte des syndromes myéloprolifératifs (SMP) ?","a":"<p>Les syndromes myéloprolifératifs sont fréquemment découverts de façon <strong>fortuite</strong>, sur un <strong>hémogramme systématique</strong> (environ 40 % des Leucémies Myéloïdes Chroniques, LMC, concernent un patient asymptomatique).</p>"},{"i":"928d363f5efe","n":317,"o":"317-3","u":"Diagnostic positif","t":"Connaître les principales circonstances diagnostiques et les signes cliniques de la LMC, de la PV et de la TE","q":"Quels sont les signes cliniques évocateurs de la Leucémie Myéloïde Chronique (LMC) ?","a":"<ul><li>Une <strong>altération de l'état général</strong>.</li><li>Une <strong>splénomégalie</strong>, fréquente, modérée à volumineuse, et isolée.</li><li>Un bilan étiologique d'une <strong>goutte</strong>.</li><li>Des manifestations thrombotiques (plus rares que dans les autres SMP) : priapisme, occlusion rétinienne.</li><li>Un possible <strong>syndrome anémique</strong>.</li></ul>"},{"i":"9a354e7f5df9","n":317,"o":"317-3","u":"Diagnostic positif","t":"Connaître les principales circonstances diagnostiques et les signes cliniques de la LMC, de la PV et de la TE","q":"Quelle complication de la maladie de Vaquez constitue une urgence médicale ?","a":"<p>Dans la maladie de Vaquez, des signes cliniques d'<strong>hyperviscosité</strong> ou un <strong>hématocrite supérieur à 60 %</strong> constituent une urgence médicale.</p>"},{"i":"f194e315a9a0","n":317,"o":"317-3","u":"Diagnostic positif","t":"Connaître les principales circonstances diagnostiques et les signes cliniques de la LMC, de la PV et de la TE","q":"Quels sont les signes cliniques évocateurs de la maladie de Vaquez (Polyglobulie de Vaquez) ?","a":"<ul><li>Un <strong>prurit aquagénique</strong> (très évocateur).</li><li>Une <strong>érythrose cutanéo-muqueuse</strong> du visage et des mains.</li><li>Une <strong>érythromélalgie</strong> (douleurs paroxystiques des extrémités, à type de brûlure, avec rougeur et chaleur, cédant à l'aspirine).</li><li>Une <strong>splénomégalie</strong> (présente dans environ 50 % des cas).</li><li>Des signes d'<strong>hyperviscosité</strong> : thromboses, HTA, signes neurosensoriels (céphalées, vertiges, troubles visuels, paresthésies, acouphènes).</li></ul>"},{"i":"fbede99aa613","n":317,"o":"317-3","u":"Diagnostic positif","t":"Connaître les principales circonstances diagnostiques et les signes cliniques de la LMC, de la PV et de la TE","q":"Quels sont les signes cliniques évocateurs de la Thrombocytémie Essentielle (TE) ?","a":"<ul><li>La maladie est le plus souvent <strong>asymptomatique</strong> lors de la découverte.</li><li>Une <strong>érythromélalgie</strong> (douleurs paroxystiques des extrémités, à type de brûlure, avec rougeur et chaleur, cédant à l'aspirine).</li><li>Une <strong>splénomégalie</strong> (habituellement absente, mais possible).</li><li>Des <strong>thromboses artérielles</strong> (cérébrales, coronaires, membres) et veineuses.</li><li>Un syndrome hémorragique rare est possible.</li></ul>"}]};